const familyChoiceHints:Record<string,[string,string]>={
 'exception-language-quiz-1':['You treated an outage as enough to stop the rehearsal. The sentence does not give you that guarantee. Start with the idea the power is out, negate it, and keep the rehearsal continues unchanged.','You reversed the rule. A continuing rehearsal does not tell you whether the power is out. Negate the power is out and make that the if side.'],
 'exception-language-quiz-2':['The rule says what happens without a heat shield, not that a shield prevents every possible overheating event.','Overheating could have another source. Does the sentence identify a missing shield as its only possible source?'],
 'exception-language-quiz-3':['Until fixes what holds before the river freezes. It does not settle the ferry’s later operation.','The ferry’s operation does not prove the river has not frozen; the stated boundary leaves the later case open.'],
 'exception-language-quiz-4':['A torn label is the stated exception, not a guarantee that the sample is discarded. Negate the label is torn and make that the if side.','The sentence does not forbid keeping a sample with a torn label. Start from the label is not torn.'],
 'exclusion-language-quiz-1':['The rule assigns no sale status to kayaks outside the rented group.','This would put rental and sale status together, the combination the sentence excludes.'],
 'exclusion-language-quiz-2':['A copy that is not a field copy is not assigned confidentiality by this rule.','Check whether this would put one copy in the very pair of categories the sentence excludes.'],
 'exclusion-language-quiz-3':['The sentence does not say what every nonreserve tank contains.','This would combine reserve-tank status with the excluded drinking-water property.'],
 'exclusion-language-quiz-4':['A specimen outside this scan’s approved group might be radioactive or not; neither status was assigned.','Does this proposed rule combine radioactivity with approval for this scan, despite the exclusion?'],
};
for(const items of Object.values(fullCourseQuiz)) for(const item of items){
  const hints=familyChoiceHints[item.id];
  if(hints) for(const option of item.options) {
    if(option.id==='answer-2') option.hint=hints[0];
    if(option.id==='answer-3') option.hint=hints[1];
  }
}

function build(id:string,prompt:string,names:string[],left:Formula,right:Formula,hint:string,explanation:string):FullCourseItem {return {kind:'build-rule',id,prompt,atoms:labels(...names),target:{if:left,then:right},hint,explanation,sourceRefs:PROVENANCE};}
function caseItem(id:string,prompt:string,names:string[],premises:Formula[],target:Formula,explanation:string):FullCourseItem {return {kind:'case',id,prompt,atoms:labels(...names),premises,target,task:'counterexample',hint:'Keep every given premise true while making the proposed conclusion false.',explanation,sourceRefs:PROVENANCE};}
function chain(id:string,prompt:string,names:string[],edges:[Formula,Formula,string][],start:Formula,target:Formula):FullCourseItem {return {kind:'chain',id,prompt,atoms:labels(...names),rules:edges.map(([left,right,text],i)=>({id:`link-${i+1}`,text,rule:{if:left,then:right}})),start,target,hint:'Choose a rule whose whole sufficient condition is already established. Its result can supply the next condition.',explanation:'The selected connections preserve the same subject and establish the requested result.',sourceRefs:PROVENANCE};}
function argument(id:string,prompt:string,names:string[],premises:Formula[],conclusion:Formula):FullCourseItem {return {kind:'argument',id,prompt,atoms:labels(...names),premises,conclusion,assumptions:[{id:'bridge',text:`If ${names[1]}, then ${names[2]}.`,formula:rule(b,c)},{id:'reverse',text:`If ${names[2]}, then ${names[1]}.`,formula:rule(c,b),hint:'This points back toward the existing middle condition rather than reaching the conclusion.'},{id:'inverse',text:`If not ${names[1]}, then not ${names[2]}.`,formula:rule(not(b),not(c)),hint:'This does not establish the needed result for a case meeting the given condition.'}],correctAssumptionId:'bridge',hint:'The added rule must make the conclusion unavoidable when combined with these premises.',explanation:`The ${names[1]} condition connects to ${names[2]}, closing this particular argument.`,sourceRefs:PROVENANCE};}

