export function makeFullCourseDrillSets(lessons: {id:string;title:string;unitId:string;part:number}[]):FullCourseDrillSet[] {
  return lessons.filter(l=>!['two-way-rules','direct-chains'].includes(l.id)).map(lesson=>({id:`${lesson.id}-practice`,title:drillTitles[lesson.id]??`Practice: ${lesson.title}`,unitId:lesson.unitId,part:lesson.part,afterLessonId:lesson.id,instructions:drillInstructions[lesson.id]??['Use the stated premises to build the requested relationship, or construct a case that tests the proposed conclusion.','Keep subjects, negatives and restrictions attached to their ideas. Attempt the task before checking the explanation.'],items:lesson.id==='contextual-two-way'?[...fullCoursePractice['two-way-rules'],...fullCoursePractice[lesson.id]]:lesson.id==='hidden-chain'?[...fullCoursePractice['direct-chains'],...fullCoursePractice[lesson.id]]:fullCoursePractice[lesson.id]??[],sourceRefs:PROVENANCE,requiredForEditionCompletion:lesson.id!=='nested-extension',requiredAllOfUnitIDs:drillAccess[lesson.id]??[lesson.unitId]}));
}

// Several operations deliberately use one fresh scenario. They are retrieval and
// comparison within a set, not additional independent transfer situations.
function addTranslationPractice(id:string,sentence:string,names:string[],left:Formula,right:Formula,explanation:string) {
  fullCoursePractice[id].push(
    build(`${id}-construct-fresh`,`${sentence} Build an equivalent conditional.`,names,left,right,'Read the whole sentence before placing the complete conditions.',explanation),
    build(`${id}-contrapose-fresh`,`${sentence} Build the equivalent contrapositive of the relationship just constructed.`,names,not(right),not(left),'Reverse and negate the complete sides, keeping existing negatives.',explanation),
    caseItem(`${id}-reverse-test`,`${sentence} Someone reverses the rule. Construct a case that satisfies the original but defeats that proposed reverse.`,names,[rule(left,right)],rule(right,left),'The original permits the required result without the sufficient condition unless another rule excludes that case.'),
    caseItem(`${id}-inverse-test`,`${sentence} Someone denies the sufficient condition and concludes the required result is absent. Construct a counterexample.`,names,[rule(left,right),not(left)],not(right),'A missing sufficient condition can coexist with the required result, so the inverse is not established.'),
  );
}
